#include "local_embedding.h"
#include <iostream>
int main(int argc,char **argv){ if(argc<2)return 2; bool cpuError=false;llama_log_set([](ggml_log_level level,const char* text,void* user){if(level==GGML_LOG_LEVEL_ERROR && (std::string(text).find("no CPU backend found")!=std::string::npos || std::string(text).find("no backends are loaded")!=std::string::npos))*static_cast<bool*>(user)=true;},&cpuError);bool cpuBefore=ggml_backend_dev_by_type(GGML_BACKEND_DEVICE_TYPE_CPU)!=nullptr;bool missingCpuReproduced=false;try{LocalEmbedding negative(argv[1]);}catch(const EmbeddingFailure&error){missingCpuReproduced=!cpuBefore && std::string(error.what()).find("MODEL_LOAD|MODEL_LOAD_NULL")==0;}local_embedding_cpu();llama_backend_init();try{LocalEmbedding engine(argv[1]);auto q=engine.embed("task: search result | query: How do I reset my password?");auto a=engine.embed("title: none | text: To recover account access, use the forgot password link and confirm the email.");auto b=engine.embed("title: none | text: Banana bread is baked with ripe fruit, flour and butter.");double same=0,other=0,norm=0;for(int i=0;i<768;i++){same+=q[i]*a[i];other+=q[i]*b[i];norm+=q[i]*q[i];}std::cout<<"{\"cpuInitiallyRegistered\":"<<(cpuBefore?"true":"false")<<",\"missingCpuFailureReproduced\":"<<(missingCpuReproduced?"true":"false")<<",\"nativeBackendMissingErrorObserved\":"<<(cpuError?"true":"false")<<",\"architecture\":\"gemma-embedding\",\"dimensions\":"<<engine.dimension()<<",\"norm\":"<<norm<<",\"relevantCosine\":"<<same<<",\"unrelatedCosine\":"<<other<<"}"<<std::endl;return missingCpuReproduced&&cpuError&&same>other&&fabs(norm-1)<0.001?0:1;}catch(const std::exception&x){std::cerr<<x.what()<<std::endl;return 3;}}
